/** Private actual native recipe fixture. Ingredients/fuel and waiting supplied; no XP, quest, recipe history or output injected. */
final class BlacksmithProductionRuntime {
 static void run(GameTestHelper h,ServerPlayer p)throws Exception{
  var level=h.getLevel();var server=level.getServer();var forge=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.BLACKSMITH.buildingId())).findFirst().orElseThrow();var b=BlueprintRegistry.get(forge.blueprint(),1);var counter=forge.origin().offset(b.rotate(b.home(),forge.rotation()));
  DimensionTravelRuntimeTests.seed(server,3);near(p,counter);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(forge.npc()));
  h.assertTrue(CommerceService.store(server).professions(p.getUUID()).isActive(Profession.BLACKSMITH)&&CommerceService.store(server).professions(p.getUUID()).track(Profession.BLACKSMITH).xp()==0,"Real paid forge/enrollment and zero starting quest XP");
  p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(Items.COAL,32));p.getInventory().setItem(1,new ItemStack(Items.CHARCOAL,32));deliver(h,p,CraftDeliveryQuests.FUEL,90000);h.assertTrue(p.getInventory().countItem(Items.COAL)==0&&p.getInventory().countItem(Items.CHARCOAL)==0,"Both real fuel variants permanently consumed64total");
  boolean refused=false;try{ProfessionService.review(p,"materials:"+CraftDeliveryQuests.IRON);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Inventory stock alone cannot satisfy native iron production");
  var furnacePos=forge.origin().offset(b.rotate(new BlockPos(3,1,7),forge.rotation()));var furnace=(AbstractFurnaceBlockEntity)level.getBlockEntity(furnacePos);near(p,furnacePos);p.openMenu(furnace);var menu=p.containerMenu;h.assertTrue(menu instanceof BlastFurnaceMenu,"Actual native forge blast furnace menu");p.getInventory().setItem(0,new ItemStack(Items.RAW_IRON,32));p.getInventory().setItem(1,new ItemStack(Items.COAL,4));menu.quickMoveStack(p,30);menu.quickMoveStack(p,31);
  for(int tick=0;tick<3250;tick++)AbstractFurnaceBlockEntity.serverTick(level,furnacePos,level.getBlockState(furnacePos),furnace);
  h.assertTrue(furnace.getItem(0).isEmpty()&&furnace.getItem(1).isEmpty()&&furnace.getItem(2).is(Items.IRON_INGOT)&&furnace.getItem(2).getCount()==32,"Native blasting consumes32raw iron/4coal and produces32actual iron");menu.quickMoveStack(p,2);p.closeContainer();h.assertTrue(CraftQuestEvidence.count(p,Profession.BLACKSMITH,ProfessionRank.APPRENTICE,"minecraft:iron_ingot")==32,"Actual registered raw-iron blasting receipt credits exact native output once");near(p,counter);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(forge.npc()));deliver(h,p,CraftDeliveryQuests.IRON,90100);h.assertTrue(p.getInventory().countItem(Items.IRON_INGOT)==0,"Native processed32iron permanently delivered");
  var table=forge.origin().offset(b.rotate(new BlockPos(11,1,9),forge.rotation())); // Onsite smithing table is not a crafting table; use the real nearby supplied table below.
  var work=forge.origin().offset(19,0,0);level.getChunk(work.getX()>>4,work.getZ()>>4);level.setBlock(work.below(),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);h.assertTrue(level.getBlockState(work).isAir(),"Private crafting station never overwrites existing building");p.getInventory().selected=0;p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.CRAFTING_TABLE));near(p,work);p.gameMode.useItemOn(p,level,p.getMainHandItem(),net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(work.below()).add(0,.5,0),Direction.UP,work.below(),false));h.assertTrue(p.getMainHandItem().isEmpty(),"Actual supplied crafting table placed natively");table=work;
  var craft=new CraftingMenu(71,p.getInventory(),ContainerLevelAccess.create(level,table));p.containerMenu=craft;for(int n=0;n<9;n++)recipe(h,p,craft,Items.LIGHTNING_ROD,new int[]{2,5,8},Items.COPPER_INGOT,new int[]{},Items.STICK);p.closeContainer();near(p,counter);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(forge.npc()));deliver(h,p,CraftDeliveryQuests.RODS,90200);h.assertTrue(p.getInventory().countItem(Items.LIGHTNING_ROD)==1,"Eight actual crafted rods consumed and one legitimate surplus preserved");
  near(p,table);craft=new CraftingMenu(72,p.getInventory(),ContainerLevelAccess.create(level,table));p.containerMenu=craft;recipe(h,p,craft,Items.IRON_PICKAXE,new int[]{1,2,3},Items.IRON_INGOT,new int[]{5,8},Items.STICK);recipe(h,p,craft,Items.IRON_AXE,new int[]{1,2,4},Items.IRON_INGOT,new int[]{5,8},Items.STICK);recipe(h,p,craft,Items.IRON_SHOVEL,new int[]{2},Items.IRON_INGOT,new int[]{5,8},Items.STICK);recipe(h,p,craft,Items.IRON_HOE,new int[]{1,2},Items.IRON_INGOT,new int[]{5,8},Items.STICK);p.closeContainer();near(p,counter);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(forge.npc()));deliver(h,p,CraftDeliveryQuests.TOOLS,90300);for(var item:List.of(Items.IRON_PICKAXE,Items.IRON_AXE,Items.IRON_SHOVEL,Items.IRON_HOE))h.assertTrue(p.getInventory().countItem(item)==0,"Actual four distinct forged tools permanently consumed");
  near(p,table);craft=new CraftingMenu(73,p.getInventory(),ContainerLevelAccess.create(level,table));p.containerMenu=craft;for(int n=0;n<4;n++)recipe(h,p,craft,Items.SHIELD,new int[]{1,3,4,5,6,8},Items.OAK_PLANKS,new int[]{2},Items.IRON_INGOT);p.closeContainer();near(p,counter);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(forge.npc()));deliver(h,p,CraftDeliveryQuests.SHIELDS,90400);
  var roster=CommerceService.store(server).professions(p.getUUID());h.assertTrue(roster.track(Profession.BLACKSMITH).xp()==500&&roster.track(Profession.BLACKSMITH).completedQuestIds().size()==5&&roster.rank(Profession.BLACKSMITH,ProfessionService.quests())==ProfessionRank.APPRENTICE&&p.getInventory().countItem(Items.SHIELD)==0,"Five native full-quantity objectives earn500XP once; no missing repair/contract/assessment or Journeyman rank fabricated");CommerceService.verifyReceipt(p);var reopened=EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data"));h.assertTrue(reopened.professions(p.getUUID()).equals(roster)&&ConstructionService.structureIntact(level,forge),"Exact native/canonical receipts reopen and operating furnace preserves forge services");
  com.mojang.logging.LogUtils.getLogger().info("NATIVE_SMITH_PRODUCTION_PASSED: real paid/enrolled forge, mixed64fuel DEL, native32raw-iron blast/consumption, actual9rods/8DEL, four native forged tools/DEL, four shields/DEL,500earnedXP/Apprentice/replay refusal/native receipt reopen; supplied ingredients/fuel/wait and seededTier3explicit, no XP/rank/quest/native output injected");
 }
 static void recipe(GameTestHelper h,ServerPlayer p,CraftingMenu menu,Item result,int[] first,Item a,int[] second,Item c){for(int i=1;i<=9;i++)menu.getSlot(i).set(ItemStack.EMPTY);for(int i:first)menu.getSlot(i).set(new ItemStack(a));for(int i:second)menu.getSlot(i).set(new ItemStack(c));h.assertTrue(menu.getSlot(0).getItem().is(result),"Actual native recipe for "+result);menu.quickMoveStack(p,0);}
 static void near(ServerPlayer p,BlockPos pos){p.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()-1.5);p.serverLevel().getChunkSource().move(p);}
 static void deliver(GameTestHelper h,ServerPlayer p,String id,long sequence)throws Exception{var q=CommerceService.handle(p,new CommerceRequest(sequence+1,1,7,"materials:"+id,1,CommerceRequest.NONE));h.assertTrue(q.reviewing(),"Normal Royal reviewed native delivery "+id);CommerceService.handle(p,new CommerceRequest(sequence+2,2,7,"materials:"+id,1,q.review()));h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.BLACKSMITH).completedQuestIds().contains(id),"Canonical native receipt commits "+id);boolean denied=false;try{ProfessionService.review(p,"materials:"+id);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Native production delivery cannot award twice");}
}
